public async Task<Order> CreateOrderAsync(CreateOrderDto dto, CancellationToken ct) {
    var order = new Order {
        Id = Guid.NewGuid(),
        CustomerId = dto.CustomerId,
        Total = dto.Total,
        Status = "confirmed"
    };

    var evt = new OutboxMessage {
        AggregateId = order.Id,
        EventType = "OrderCreated",
        Payload = JsonSerializer.Serialize(order),
        Status = "pending"
    };

    _db.Orders.Add(order);
    _db.OutboxMessages.Add(evt);
    await _db.SaveChangesAsync(ct);
    return order;
}

public class OutboxRelay : BackgroundService {
    private readonly IServiceProvider _services;
    private readonly IMessageBus _bus;
    private readonly TimeSpan _interval = TimeSpan.FromSeconds(5);

    public OutboxRelay(IServiceProvider services, IMessageBus bus) {
        _services = services;
        _bus = bus;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        while (!stoppingToken.IsCancellationRequested) {
            using var scope = _services.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDb>();

            var pending = await db.OutboxMessages
                .Where(m => m.Status == "pending")
                .OrderBy(m => m.CreatedAt)
                .Take(50)
                .ToListAsync(stoppingToken);

            foreach (var msg in pending) {
                try {
                    await _bus.PublishAsync(msg.EventType, msg.Payload, msg.Id);
                    msg.Status = "published";
                    msg.PublishedAt = DateTime.UtcNow;
                }
                catch (Exception ex) {
                    msg.RetryCount = (msg.RetryCount ?? 0) + 1;
                    if (msg.RetryCount >= 5)
                        msg.Status = "dead-letter";
                }
            }
            await db.SaveChangesAsync(stoppingToken);
            await Task.Delay(_interval, stoppingToken);
        }
    }
}
